// 1. Spatial Locality: Row-major array access (C/C++)
void iterate_rows(int M, int N, int A[M][N]) {
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            A[i][j] *= 2; // Contiguous access
        }
    }
}

// 2. Temporal Locality: Loop invariant data reuse
int sum_matrix(int M, int N, int A[M][N]) {
    int total = 0;
    for (int i = 0; i < M; i++) {
        // A[i] is repeatedly used (Temporal)
        for (int j = 0; j < N; j++) {
            total += A[i][j];
        }
    }
    return total;
}

// 3. Cache Unfriendly: Column-major access (Stride issue)
void iterate_cols_slow(int M, int N, int A[M][N]) {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < M; i++) {
            A[i][j] = 0; // Large stride (cache line miss risk)
        }
    }
}

// 4. Cache Blocking / Tiling (2D array multiplication)
// Optimization for L1/L2 data reuse (B is block size)
void blocked_mmul(int N, int A[N][N], int B) {
    for (int jj = 0; jj < N; jj += B)
        for (int kk = 0; kk < N; kk += B)
            for (int i = 0; i < N; i++)
                for (int j = jj; j < jj + B; j++)
                    for (int k = kk; k < kk + B; k++)
                        A[i][j] += 1;
}
